"""For a dissection choice: per vertex class, density d (per unit physical volume, inside a ball in the patch), the covolume of the lattice generated by the class,
the implied window volume d*covol, and the volume of the convex hull of the class's star positions. For a model set d*covol equals the window volume;
a convex hull much larger than d*covol means the cloud is not a convex window."""
import sys, time, json, collections
sys.path.insert(0, '.')
import numpy as np, sympy
from scipy.spatial import ConvexHull
from sympy.matrices.normalforms import hermite_normal_form
import t9_dissect as d, t9_patch as P
COVZ6 = 2 * 40 * 5 ** .5 / 2 * d.tau ** 3        # covolume of Z^6 in the star frame: |det A| tau^3 = 40 sqrt5 tau^3
def lattice_covol(pts):
    base = np.array(pts[0]); D = [list(np.array(p) - base) for p in pts[1:40]]
    H = hermite_normal_form(sympy.Matrix(D).T); assert H.shape == (6, 6), H.shape
    return abs(float(H.det())) / 4 ** 6 * COVZ6
def run(choice, levels=9, minpts=40):
    tiles = P.grow(choice, levels)
    V4 = np.rint(np.array([np.linalg.matrix_power(d.S, levels) @ v for v in d.T4["K"]])).astype(int)
    V = np.array([d.phys4(v) for v in V4]); cen = V.mean(0); dist = []
    for i in range(4):
        f = [V[j] for j in range(4) if j != i]; n = np.cross(f[1] - f[0], f[2] - f[0]); n /= np.linalg.norm(n); dist.append(abs(n @ (cen - f[0])))
    rad = 0.7 * min(dist); vb = 4 / 3 * np.pi * rad ** 3
    verts = set()
    for T, g, x in tiles:
        for j in range(4): verts.add(tuple(int(z) for z in (x + d.RX[g] @ d.T4[T][j])))
    cls = collections.defaultdict(list)
    for v in verts: cls[P.class_key(v)].append(v)
    out = []
    for k, vs in cls.items():
        inb = [v for v in vs if np.linalg.norm(d.phys4(v) - cen) <= rad]
        if len(inb) < minpts: continue
        st = np.array([d.star4(v) for v in vs]); hull = ConvexHull(st).volume
        cv = lattice_covol(vs); dens = len(inb) / vb
        out.append((k, len(inb), dens, cv, dens * cv, hull))
    return out
if __name__ == "__main__":
    import t9_dissect_faces as F
    NC = int(sys.argv[1]) if len(sys.argv) > 1 else 3
    for nf, ch in F.FAILS[:NC]:
        print(nf, ch)
        for k, n, dens, cv, wv, hull in sorted(run(ch), key=lambda r: -r[2]):
            print("   class", k, "n=%d density %.4f covol %.2f  d*covol %.2f  hull %.2f" % (n, dens, cv, wv, hull))

